def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # All demonstrations show that the irregular interior of each patterned
    # frame is copied into the geometrically corresponding blank frame of the
    # same size, recolored as that frame. Preserve each frame's exact layout.
    def bbox(color):
        cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        return (min(r for r, c in cells), max(r for r, c in cells),
                min(c for r, c in cells), max(c for r, c in cells))

    # Select the pattern-bearing object and the blank frame by equal outer size.
    colors = {v for row in grid for v in row if v}
    boxes = {color: bbox(color) for color in colors}
    patterned = []
    empty = []
    for color, (y0, y1, x0, x1) in boxes.items():
        if y1 - y0 < 2 or x1 - x0 < 2:
            continue
        mask = {(r-y0, c-x0) for r in range(y0+1, y1)
                for c in range(x0+1, x1) if grid[r][c] == color}
        if mask:
            patterned.append((color, y0, y1, x0, x1, mask))
        else:
            empty.append((color, y0, y1, x0, x1))

    # Match based on bounding-box dimensions and copy, without scaling.
    for sc, sy0, sy1, sx0, sx1, mask in patterned:
        for dc, dy0, dy1, dx0, dx1 in empty:
            if (sy1-sy0, sx1-sx0) != (dy1-dy0, dx1-dx0):
                continue
            for y in range(1, dy1-dy0):
                for x in range(1, dx1-dx0):
                    out[dy0+y][dx0+x] = dc if (y, x) in mask else 0
    return out
